    'RegistrationText'=>'登録された SimpleRisk インスタンスには、Upgrade and Secure Controls Framework (SCF) Extras へのアクセスがすぐに付与されます。 Upgrade Extra は、ボタンをクリックするだけで SimpleRisk インスタンスをバックアップおよびアップグレードする機能を提供します。 Secure Controls Framework (SCF) Extra は、SimpleRisk Governance 機能に統合された共通のコントロール フレームワークを提供します。 SimpleRisk を登録すると、SimpleRisk がホストするサーバーに登録情報が送信されます。提供された登録情報は、SimpleRisk が新しいリリースとセキュリティ アップデートを顧客に通知するために使用されます。 SimpleRisk を登録する行為により、当社のマーケティング コミュニケーションにオプトインできますが、これらのコミュニケーションの登録解除リンクを使用して、いつでもオプトアウトすることができます。 SimpleRisk はお客様のプライバシーを尊重し、SimpleRisk 登録プロセスを通じて提供された情報が第三者に販売されることはありません。',
