    'SCFExtraDesc'                        => "Secure Controls Framework (SCF) Extraは、Secure Controls FrameworkとSimpleRiskを直接統合したものです。SCFのコントロールカタログと、幅広いコンプライアンスおよびサイバーセキュリティフレームワークにおけるそれらのマッピングをSimpleRiskのガバナンス機能にインポートすることで、必要なフレームワークを採用し、コントロールを手動で構築することなく管理できます。",

