    'SoaEvidencePolicy' => 'ポリシー',
    'SoaEvidenceStandard' => '標準',
    'SoaEvidenceProcedure' => '手順',
    'SoaEvidenceGuideline' => 'ガイドライン',
    // ── The legend, grouped by column (SOA_LEGEND_GROUPS, includes/soa.php) ──
